#!/usr/bin/env node
// Version-matched API lookup (docs/specs/grounded-evidence.md, AC-1 to AC-5). Answers "does this
// API exist in the version we have installed?" from what is installed: an npm package's version,
// lock entry, type declarations, and bundled docs, or an Unreal engine's headers. Reads only, uses
// no dependencies, and makes no network calls.
//
// Usage:
//   node checks/api-lookup.mjs npm <package> [symbol] [--root <dir>] [--max <n>] [--json]
//   node checks/api-lookup.mjs unreal <symbol> [--engine <dir>]... [--under <path>] [--max <n>] [--json]
//
// Exit codes: 0 found (or no symbol asked for), 1 symbol not declared (in any engine, for unreal),
// 2 package not installed, no engine given, or a usage error.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const DEFAULT_MAX = 10;
const DOC_DIRS = ['docs', 'dist/docs', 'doc'];
const MAX_FILES = 50000;

const toPosix = p => p.split(path.sep).join('/');
const rel = (root, p) => toPosix(path.relative(root, p)) || '.';
const escapeRe = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function readJson(file) {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch {
    return null;
  }
}

function isDir(p) {
  try {
    return fs.statSync(p).isDirectory();
  } catch {
    return false;
  }
}

function isFile(p) {
  try {
    return fs.statSync(p).isFile();
  } catch {
    return false;
  }
}

// Every file under dir whose name passes keep, skipping folders that skipDir rejects.
function walk(dir, keep, skipDir = () => false, out = []) {
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const e of entries) {
    if (out.length >= MAX_FILES) break;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) {
      if (!skipDir(e.name, p)) walk(p, keep, skipDir, out);
    } else if (e.isFile() && keep(e.name)) out.push(p);
  }
  return out;
}

function excerpt(lines, index, after = 3) {
  return lines.slice(index, Math.min(lines.length, index + 1 + after)).map(l => l.replace(/\s+$/, ''));
}

// ---------------------------------------------------------------------------------------------
// npm

function findPackageDir(root, name) {
  let dir = path.resolve(root);
  for (;;) {
    const candidate = path.join(dir, 'node_modules', ...name.split('/'));
    if (isFile(path.join(candidate, 'package.json'))) return candidate;
    const parent = path.dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}

const typesPackageName = name => name.startsWith('@') ? `@types/${name.slice(1).replace('/', '__')}` : `@types/${name}`;

// Strings under any "types" key in an exports map.
function exportTypes(exportsField, out = []) {
  if (!exportsField || typeof exportsField !== 'object') return out;
  for (const [key, value] of Object.entries(exportsField)) {
    if (key === 'types' && typeof value === 'string') out.push(value);
    else if (value && typeof value === 'object') exportTypes(value, out);
  }
  return out;
}

function lockInfo(root) {
  const files = ['package-lock.json', 'npm-shrinkwrap.json', 'pnpm-lock.yaml', 'yarn.lock', 'bun.lockb', 'bun.lock'];
  const present = files.filter(f => isFile(path.join(root, f)));
  const npm = present.find(f => f === 'package-lock.json' || f === 'npm-shrinkwrap.json');
  return { file: npm ?? null, data: npm ? readJson(path.join(root, npm)) : null, notRead: present.filter(f => f !== npm) };
}

function declaredRange(root, name) {
  const pkg = readJson(path.join(root, 'package.json'));
  if (!pkg) return null;
  for (const field of ['dependencies', 'devDependencies', 'peerDependencies', 'optionalDependencies']) {
    if (pkg[field]?.[name]) return { field, range: pkg[field][name] };
  }
  return null;
}

const isDeclarationFile = n => /\.d\.(?:[cm]?ts)$/.test(n);
const skipNested = n => n === 'node_modules' || n === '.git';

function declarationPatterns(symbol) {
  const s = escapeRe(symbol);
  return [
    { kind: 'declaration', re: new RegExp(`\\b(?:export\\s+)?(?:declare\\s+)?(?:default\\s+)?(?:abstract\\s+)?(?:async\\s+)?(function\\*?|const|let|var|class|interface|type|enum|namespace|module)\\s+${s}\\b`) },
    { kind: 'export', re: new RegExp(`\\bexport\\s*(?:type\\s*)?\\{[^}]*\\b${s}\\b[^}]*\\}`) },
    { kind: 'member', re: new RegExp(`^\\s*(?:(?:readonly|static|public|protected|private|abstract|declare|get|set)\\s+)*['"]?${s}['"]?\\??\\s*[(:<]`) },
  ];
}

function findDeclarations(files, symbol, root, max) {
  const patterns = declarationPatterns(symbol);
  const found = [];
  let total = 0;
  for (const file of files) {
    const text = fs.readFileSync(file, 'utf8');
    if (!text.includes(symbol)) continue;
    const lines = text.split(/\r?\n/);
    lines.forEach((line, i) => {
      for (const p of patterns) {
        const m = p.re.exec(line);
        if (!m) continue;
        total++;
        if (found.length < max) found.push({ file: rel(root, file), line: i + 1, kind: p.kind === 'declaration' ? m[1].replace('*', '') : p.kind, excerpt: excerpt(lines, i) });
        break;
      }
    });
  }
  return { found, total };
}

function findMentions(files, symbol, root, max) {
  const re = new RegExp(`(?<![\\w$])${escapeRe(symbol)}(?![\\w$])`);
  const found = [];
  let total = 0;
  for (const file of files) {
    const lines = fs.readFileSync(file, 'utf8').split(/\r?\n/);
    lines.forEach((line, i) => {
      if (!re.test(line)) return;
      total++;
      if (found.length < max) found.push({ file: rel(root, file), line: i + 1, text: line.trim().slice(0, 200) });
    });
  }
  return { found, total };
}

export function lookupNpm({ root = '.', name, symbol = null, max = DEFAULT_MAX }) {
  root = path.resolve(root);
  const report = { kind: 'npm', package: name, symbol, root: toPosix(root) };
  const dir = findPackageDir(root, name);
  if (!dir) {
    report.installed = null;
    report.status = 'not-installed';
    report.message = `${name} is not installed under ${toPosix(root)} or any folder above it (no node_modules/${name}/package.json).`;
    return report;
  }
  const pkg = readJson(path.join(dir, 'package.json')) ?? {};
  report.installed = { version: pkg.version ?? null, path: rel(root, dir) };

  const lock = lockInfo(root);
  const locked = lock.data?.packages?.[`node_modules/${name}`]?.version ?? lock.data?.dependencies?.[name]?.version ?? null;
  report.lock = { file: lock.file, version: locked, notRead: lock.notRead };
  report.lock.matches = locked === null ? null : locked === report.installed.version;
  report.declared = declaredRange(root, name);

  // Where the package documents itself.
  const typesEntries = [pkg.types, pkg.typings, ...exportTypes(pkg.exports)].filter(t => typeof t === 'string');
  if (!typesEntries.length && isFile(path.join(dir, 'index.d.ts'))) typesEntries.push('index.d.ts');
  const typesName = typesPackageName(name);
  const typesDir = name.startsWith('@types/') ? null : findPackageDir(root, typesName);
  const typesPkg = typesDir ? readJson(path.join(typesDir, 'package.json')) : null;
  const docDirs = DOC_DIRS.filter(d => isDir(path.join(dir, d)));
  const topFiles = fs.readdirSync(dir).filter(f => /^(readme|changelog|changes|history)(\.[\w]+)?$/i.test(f)).sort();
  report.docs = {
    types: [...new Set(typesEntries.map(t => toPosix(path.normalize(t))))],
    typesPackage: typesDir ? { name: typesName, version: typesPkg?.version ?? null, path: rel(root, typesDir) } : null,
    folders: docDirs,
    files: topFiles,
  };

  if (!symbol) {
    report.status = 'found';
    return report;
  }
  // A dotted name (Foo.bar) is looked up by its last part.
  const last = symbol.split(/\.|::/).pop();
  const declFiles = [...walk(dir, isDeclarationFile, skipNested), ...(typesDir ? walk(typesDir, isDeclarationFile, skipNested) : [])];
  const decl = findDeclarations(declFiles, last, root, max);
  const docFiles = [
    ...docDirs.flatMap(d => walk(path.join(dir, d), n => /\.(md|mdx|markdown|txt)$/i.test(n), skipNested)),
    ...topFiles.filter(f => /^readme/i.test(f)).map(f => path.join(dir, f)),
  ];
  const mentions = findMentions(docFiles, last, root, max);
  report.declarations = decl.found;
  report.declarationCount = decl.total;
  report.declarationFilesSearched = declFiles.length;
  report.mentions = mentions.found;
  report.mentionCount = mentions.total;
  report.status = decl.total ? 'found' : 'not-declared';
  if (!decl.total) {
    report.message = declFiles.length
      ? `${last} is not declared in the installed ${name} ${report.installed.version ?? ''} declaration files.`.replace('  ', ' ')
      : `${name} ${report.installed.version ?? ''} ships no declaration files, so nothing could be checked; read its source or docs.`.replace('  ', ' ');
  }
  return report;
}

// ---------------------------------------------------------------------------------------------
// Unreal

function engineDirOf(dir) {
  const abs = path.resolve(dir);
  if (isFile(path.join(abs, 'Build', 'Build.version'))) return abs;
  if (isFile(path.join(abs, 'Engine', 'Build', 'Build.version'))) return path.join(abs, 'Engine');
  return null;
}

const UE_SKIP = new Set(['ThirdParty', 'Intermediate', 'Binaries', 'Saved', 'DerivedDataCache', '.git']);

function unrealPatterns(symbol) {
  const s = escapeRe(symbol);
  return [
    { kind: 'class', re: new RegExp(`^\\s*(?:template\\s*<[^>]*>\\s*)?(?:class|struct)\\s+(?:alignas\\([^)]*\\)\\s+)?(?:[A-Z][A-Z0-9_]*_API\\s+)?${s}\\b(?!\\s*;)`) },
    { kind: 'enum', re: new RegExp(`^\\s*enum\\s+(?:class\\s+|struct\\s+)?${s}\\b(?!\\s*;)`) },
    { kind: 'namespace', re: new RegExp(`^\\s*namespace\\s+${s}\\b`) },
    { kind: 'macro', re: new RegExp(`^\\s*#\\s*define\\s+${s}\\b`) },
    { kind: 'alias', re: new RegExp(`^\\s*(?:using\\s+${s}\\s*=|typedef\\b.*\\b${s}\\s*;)`) },
    { kind: 'function', re: new RegExp(`^\\s*(?!return\\b|else\\b|if\\b|while\\b|for\\b|switch\\b|case\\b|delete\\b|new\\b)(?:[A-Za-z_][\\w:<>,]*[\\s*&]+)+${s}\\s*\\(`) },
  ];
}

function searchEngine(engineDir, symbol, { under = null, max }) {
  const [owner, member] = symbol.includes('::') ? symbol.split('::').slice(-2) : [null, symbol];
  const roots = under
    ? [path.join(engineDir, 'Source', under), path.join(engineDir, 'Plugins', under), path.join(engineDir, under)].filter(isDir)
    : [path.join(engineDir, 'Source'), path.join(engineDir, 'Plugins')].filter(isDir);
  const files = [...new Set(roots.flatMap(r => walk(r, n => /\.(h|hpp|inl)$/.test(n), n => UE_SKIP.has(n))))];
  const classPattern = owner ? unrealPatterns(owner)[0].re : null;
  const patterns = owner ? unrealPatterns(member).filter(p => p.kind === 'function' || p.kind === 'alias') : unrealPatterns(member);
  const found = [];
  let total = 0;
  for (const file of files) {
    const text = fs.readFileSync(file, 'utf8');
    if (!text.includes(member)) continue;
    const lines = text.split(/\r?\n/);
    if (classPattern && !lines.some(l => classPattern.test(l))) continue;
    lines.forEach((line, i) => {
      for (const p of patterns) {
        if (!p.re.test(line)) continue;
        total++;
        if (found.length < max) found.push({ file: rel(engineDir, file), line: i + 1, kind: p.kind, excerpt: excerpt(lines, i, 2) });
        break;
      }
    });
  }
  return { found, total, filesSearched: files.length, roots: roots.map(r => rel(engineDir, r)) };
}

export function lookupUnreal({ symbol, engines = [], under = null, max = DEFAULT_MAX }) {
  const report = { kind: 'unreal', symbol, engines: [] };
  for (const given of engines) {
    const engineDir = engineDirOf(given);
    if (!engineDir) {
      report.engines.push({ path: toPosix(path.resolve(given)), version: null, status: 'no-engine', message: 'no Engine/Build/Build.version here' });
      continue;
    }
    const v = readJson(path.join(engineDir, 'Build', 'Build.version')) ?? {};
    const version = v.MajorVersion !== undefined ? `${v.MajorVersion}.${v.MinorVersion ?? 0}.${v.PatchVersion ?? 0}` : null;
    const r = searchEngine(engineDir, symbol, { under, max });
    report.engines.push({
      path: toPosix(engineDir),
      version,
      status: r.total ? 'found' : 'not-declared',
      declarations: r.found,
      declarationCount: r.total,
      filesSearched: r.filesSearched,
      searched: r.roots,
    });
  }
  const missing = report.engines.filter(e => e.status !== 'found');
  report.status = !report.engines.length ? 'no-engine' : missing.length ? 'not-declared' : 'found';
  report.missingIn = missing.map(e => e.version ?? e.path);
  return report;
}

// ---------------------------------------------------------------------------------------------
// Output

function formatNpm(r) {
  if (r.status === 'not-installed') return r.message;
  const out = [`${r.package} ${r.installed.version ?? '(no version)'} installed at ${r.installed.path}`];
  if (r.lock.file) {
    if (r.lock.version === null) out.push(`  ${r.lock.file}: no entry for ${r.package}`);
    else out.push(`  ${r.lock.file}: ${r.lock.version}${r.lock.matches ? '' : `  (differs from the installed ${r.installed.version}: reinstall before trusting either)`}`);
  }
  if (r.lock.notRead.length) out.push(`  not read: ${r.lock.notRead.join(', ')}`);
  if (r.declared) out.push(`  package.json ${r.declared.field}: ${r.declared.range}`);
  const d = r.docs;
  out.push(`  types: ${d.types.length ? d.types.join(', ') : 'none in the package'}${d.typesPackage ? `; ${d.typesPackage.name} ${d.typesPackage.version ?? ''} at ${d.typesPackage.path}` : ''}`);
  out.push(`  docs: ${[...d.folders.map(f => `${f}/`), ...d.files].join(', ') || 'none bundled'}`);
  if (!r.symbol) return out.join('\n');
  out.push('');
  if (r.declarations.length) {
    out.push(`${r.symbol}: ${r.declarationCount} declaration(s)${r.declarationCount > r.declarations.length ? `, first ${r.declarations.length} shown` : ''}`);
    for (const x of r.declarations) {
      out.push(`  ${x.file}:${x.line} (${x.kind})`);
      for (const l of x.excerpt) out.push(`    | ${l}`);
    }
  } else out.push(r.message);
  if (r.mentions.length) {
    out.push(`${r.symbol} in the bundled docs: ${r.mentionCount} line(s)${r.mentionCount > r.mentions.length ? `, first ${r.mentions.length} shown` : ''}`);
    for (const m of r.mentions) out.push(`  ${m.file}:${m.line}: ${m.text}`);
  }
  return out.join('\n');
}

function formatUnreal(r) {
  if (r.status === 'no-engine' && !r.engines.length) return 'No engine given: pass --engine <dir> for each supported engine version, or set RFR_UE_ROOTS.';
  const out = [];
  for (const e of r.engines) {
    if (e.status === 'no-engine') {
      out.push(`${e.path}: ${e.message}`);
      continue;
    }
    out.push(`Unreal ${e.version ?? '(unknown version)'} at ${e.path}: ${e.declarationCount ? `${e.declarationCount} declaration(s) of ${r.symbol}` : `${r.symbol} is not declared in ${e.filesSearched} header(s) under ${e.searched.join(', ') || '(nothing to search)'}`}`);
    for (const x of e.declarations) {
      out.push(`  ${x.file}:${x.line} (${x.kind})`);
      for (const l of x.excerpt) out.push(`    | ${l}`);
    }
  }
  if (r.missingIn.length && r.engines.some(e => e.status === 'found')) out.push(`\nMissing in ${r.missingIn.join(', ')}: wrap its use in an ENGINE_MAJOR_VERSION / ENGINE_MINOR_VERSION check or a small wrapper (UE-001).`);
  out.push('\nPatterns cover classes, structs, enums, namespaces, macros, aliases, and function declarations; a declaration behind a macro can be missed, so the compiler stays the authority.');
  return out.join('\n');
}

export function parseArgs(argv) {
  const opts = { positional: [], engines: [], json: false, max: DEFAULT_MAX, root: '.', under: null };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--json') opts.json = true;
    else if (a === '--engine') opts.engines.push(argv[++i]);
    else if (a === '--root') opts.root = argv[++i];
    else if (a === '--under') opts.under = argv[++i];
    else if (a === '--max') opts.max = Number(argv[++i]) || DEFAULT_MAX;
    else opts.positional.push(a);
  }
  return opts;
}

const USAGE = `Usage:
  api-lookup.mjs npm <package> [symbol] [--root <dir>] [--max <n>] [--json]
  api-lookup.mjs unreal <symbol> [--engine <dir>]... [--under <path>] [--max <n>] [--json]`;

export function run(argv, env = process.env) {
  const opts = parseArgs(argv);
  const [mode, a, b] = opts.positional;
  if (mode === 'npm' && a) {
    const r = lookupNpm({ root: opts.root, name: a, symbol: b ?? null, max: opts.max });
    return { report: r, text: opts.json ? JSON.stringify(r, null, 2) : formatNpm(r), code: r.status === 'found' ? 0 : r.status === 'not-declared' ? 1 : 2 };
  }
  if (mode === 'unreal' && a) {
    const engines = opts.engines.length ? opts.engines : (env.RFR_UE_ROOTS ?? '').split(path.delimiter).filter(Boolean);
    const r = lookupUnreal({ symbol: a, engines, under: opts.under, max: opts.max });
    return { report: r, text: opts.json ? JSON.stringify(r, null, 2) : formatUnreal(r), code: r.status === 'found' ? 0 : r.status === 'not-declared' ? 1 : 2 };
  }
  return { report: null, text: USAGE, code: 2 };
}

if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(fileURLToPath(import.meta.url))) {
  const { text, code } = run(process.argv.slice(2));
  (code === 2 && !text.includes('installed') && !text.includes('engine') ? console.error : console.log)(text);
  process.exit(code);
}

