// A package's declaration files, plus those of packages it re-exports from (`export * from 'other'`),
// up to MAX_REEXPORTS packages, so that a wrapper such as playwright -> playwright-core is followed.
const MAX_REEXPORTS = 5;
const REEXPORT_RE = /\bexport\s+(?:type\s+)?(?:\*|\*\s+as\s+\w+|\{[^}]*\})\s+from\s+['"]([^./'"][^'"]*)['"]/g;
const packageOf = spec => spec.startsWith('@') ? spec.split('/').slice(0, 2).join('/') : spec.split('/')[0];

function declarationFilesWithReexports(dir, typesDir) {
  const files = [...walk(dir, isDeclarationFile, skipNested), ...(typesDir ? walk(typesDir, isDeclarationFile, skipNested) : [])];
  const seen = new Set([dir, typesDir].filter(Boolean));
  const reexports = [];
  for (let i = 0; i < files.length && reexports.length < MAX_REEXPORTS; i++) {
    const text = fs.readFileSync(files[i], 'utf8');
    for (const m of text.matchAll(REEXPORT_RE)) {
      const name = packageOf(m[1]);
      const other = findPackageDir(path.dirname(files[i]), name);
      if (!other || seen.has(other) || reexports.length >= MAX_REEXPORTS) continue;
      seen.add(other);
      reexports.push({ name, dir: other, version: readJson(path.join(other, 'package.json'))?.version ?? null });
      files.push(...walk(other, isDeclarationFile, skipNested));
    }
  }
  return { files, reexports };
}

